import { ChangeDetectorRef, Component, EventEmitter, Input, Output } from '@angular/core';
import { MatSelectModule } from '@angular/material/select';
import { ButtonComponent } from '../../button/button.component';
import { IconComponent } from '../../icon/icon.component';
import { TaskFormComponent } from '../task-form/task-form.component';
import { MatDialog } from '@angular/material/dialog';
import { TostbarService } from '../../../../core/services/tost/tostbar.service';
import { TaskService } from '../../../services/task/task.service';
import { AvatarComponent } from '../../avatar/avatar.component';
import { MatTooltipModule } from '@angular/material/tooltip';
import { FormsModule } from '@angular/forms';
import { CommonModule } from '@angular/common';
import { CommonService } from '../../../services/common/common.service';
import { SelectedTasksComponent } from '../selected-tasks/selected-tasks.component';
import { O } from '@angular/cdk/keycodes';

@Component({
  selector: 'choose-task',
  standalone: true,
  imports: [CommonModule, ButtonComponent, IconComponent, AvatarComponent, MatTooltipModule, FormsModule, MatSelectModule, SelectedTasksComponent],
  templateUrl: './choose-task.component.html',
  styleUrl: './choose-task.component.scss'
})
export class ChooseTaskComponent {
  @Input() selectedTasks: any[];
  @Input() nCaseid: string;
  @Input() ismyfiles: boolean = false;
  @Output() changeTask: EventEmitter<string> = new EventEmitter();
  taskList: any[] = [];
  nTaskid: number | null = null;
  choosedtask: any;
  isLoading: boolean = true;
  dialogRef: any;
  @Input() isSuccess: boolean = false;
  @Input() nopadding: boolean = false;
  constructor(private taskS: TaskService, private cdr: ChangeDetectorRef, private dialog: MatDialog, private tost: TostbarService, private common: CommonService) {

  }


  async ngOnInit() {
    this.taskList = await this.taskS.getTaskList(this.nCaseid, this.ismyfiles ? 'F' : 'FT');
    this.taskList[0].map(a => {
      var user = this.taskList[1].filter(b => b.nTaskid == a.nTaskid);
      a['teamlist'] = user ? user : [];
    });
    console.log(this.taskList[0]);
    if (this.nTaskid) {
      this.selectedTask();
      if (this.selectedTasks && this.selectedTasks.length > 0) {
        const ind = this.selectedTasks.findIndex(a => a.nTaskid == this.choosedtask.nTaskid);
        this.selectedTasks.splice(ind, 1);
        this.selectedTasks.unshift(this.choosedtask);
      }
    }
    this.isLoading = false;
    this.cdr.detectChanges();
  }


  selectedTask() {
    this.choosedtask = this.taskList[0].find(a => a.nTaskid == this.nTaskid);
    console.log(this.choosedtask);
    this.cdr.detectChanges();
  }


  addTask(flag) {
    if (this.dialogRef) return;
    this.dialogRef = this.dialog.open(TaskFormComponent, {
      maxWidth: '600px',
      // height: 'calc(100% - 220px)',
      width: !this.ismyfiles ? '440px' : 'calc(var(--rightpanelwidth) + 16px)',
      height: !this.ismyfiles ? 'calc(100vh - 56px)' : 'calc(100% - 220px)',
      position: !this.ismyfiles ? { right: '0vh', top: '56px' } : { right: '24px', top: '200px' },
      hasBackdrop: false,
      panelClass: 'noshadow'
      // data: {nCaseid:this.nCaseid}
    });
    this.dialogRef.componentInstance.nCaseid = this.nCaseid;
    this.dialogRef.componentInstance.ismyfiles = this.ismyfiles;
    if (flag == 'E') {
      this.dialogRef.componentInstance.editable_list = this.choosedtask;
    }
    this.dialogRef.afterClosed().subscribe(result => {
      this.dialogRef = null;
      if (result) {
        this.nTaskid = result;
        this.isLoading = true;
        this.ngOnInit();
      }
    });
  }


  SaveTask() {
    
    if (!this.choosedtask) return;
    const ind = this.selectedTasks.findIndex(a => a.nTaskid == this.choosedtask.nTaskid);
    if (ind == -1) {
      this.selectedTasks.unshift(this.choosedtask);
      // this.selectedContacts = [...this.selectedContacts]
      this.choosedtask = null;
      this.nTaskid = null;
    } else {
      this.tost.openSnackBar('Task already added', 'E');
    }
    this.cdr.detectChanges();
    this.changeTask.emit('SUBMIT');
  }


  view() {
    this.changeTask.emit('VIEW');
  }

}
